namespace sv_adad7b56c162456aa128b1ccf6fb4ecf.Services;

public class WarehouseState
{
    private string _currentWarehouseId = "WH-001";

    public string CurrentWarehouseId => _currentWarehouseId;

    public string CurrentWarehouseName =>
        Warehouses.FirstOrDefault(w => w.Id == _currentWarehouseId)?.Name ?? "Unknown";

    public IReadOnlyList<WarehouseInfo> Warehouses { get; } =
    [
        new("WH-001", "Warehouse A — Main Distribution"),
        new("WH-002", "Warehouse B — East Regional"),
        new("WH-003", "Warehouse C — West Regional"),
        new("WH-004", "Warehouse D — Cold Storage"),
    ];

    public event Action? OnChange;

    public void SetWarehouse(string warehouseId)
    {
        if (_currentWarehouseId == warehouseId) return;
        _currentWarehouseId = warehouseId;
        OnChange?.Invoke();
    }
}

public record WarehouseInfo(string Id, string Name);

namespace sv_adad7b56c162456aa128b1ccf6fb4ecf.Services;

public class InventoryAlertService
{
    private readonly Random _random = new();

    public int LatestLowStockCount { get; private set; }

    /// <summary>
    /// Fired when new alert data arrives. Subscribers should call InvokeAsync(StateHasChanged).
    /// </summary>
    public event Action? OnAlertDataChanged;

    /// <summary>
    /// Simulates a database query returning the number of items below minimum stock levels.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        var count = _random.Next(0, 16);
        return Task.FromResult(count);
    }

    /// <summary>
    /// Called by the polling component to update the shared count and notify all subscribers.
    /// </summary>
    public void UpdateAlertCount(int newCount)
    {
        LatestLowStockCount = newCount;
        OnAlertDataChanged?.Invoke();
    }
}

