@using sv_adad7b56c162456aa128b1ccf6fb4ecf.Services
@inject WarehouseState WarehouseState
@implements IDisposable
@rendermode InteractiveServer

<div class="warehouse-selector">
    <label for="warehouse-dropdown"><strong>Current Warehouse:</strong></label>
    <select id="warehouse-dropdown" class="form-select form-select-sm d-inline-block w-auto ms-2"
            @onchange="OnWarehouseChanged" value="@WarehouseState.CurrentWarehouseId">
        @foreach (var wh in WarehouseState.Warehouses)
        {
            <option value="@wh.Id" selected="@(wh.Id == WarehouseState.CurrentWarehouseId)">@wh.Name</option>
        }
    </select>
</div>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnChange += OnStateChanged;
    }

    private void OnWarehouseChanged(ChangeEventArgs e)
    {
        var newId = e.Value?.ToString();
        if (!string.IsNullOrEmpty(newId))
        {
            WarehouseState.SetWarehouse(newId);
        }
    }

    private void OnStateChanged() => InvokeAsync(StateHasChanged);

    public void Dispose()
    {
        WarehouseState.OnChange -= OnStateChanged;
    }
}

@using sv_adad7b56c162456aa128b1ccf6fb4ecf.Services
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<span class="alert-badge position-relative">
    <span class="bi bi-exclamation-triangle-fill-nav-menu" aria-hidden="true"></span>
    @if (AlertService.LatestLowStockCount > 0)
    {
        <span class="badge bg-danger rounded-pill">@AlertService.LatestLowStockCount</span>
    }
    else
    {
        <span class="badge bg-success rounded-pill">0</span>
    }
</span>

@code {
    private Action? _handler;

    protected override void OnInitialized()
    {
        _handler = () => InvokeAsync(StateHasChanged);
        AlertService.OnAlertDataChanged += _handler;
    }

    public void Dispose()
    {
        if (_handler is not null)
        {
            AlertService.OnAlertDataChanged -= _handler;
        }
    }
}

