@page "/dashboard"
@using sv_adad7b56c162456aa128b1ccf6fb4ecf.Services
@inject WarehouseState WarehouseState
@inject InventoryAlertService AlertService
@implements IAsyncDisposable
@rendermode InteractiveServer

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">Current Warehouse</h5>
        <p class="card-text fs-4">@WarehouseState.CurrentWarehouseName</p>
        <p class="text-muted">ID: @WarehouseState.CurrentWarehouseId</p>
    </div>
</div>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">
            Low Stock Alerts
            @if (AlertService.LatestLowStockCount > 0)
            {
                <span class="badge bg-danger ms-2">@AlertService.LatestLowStockCount items</span>
            }
            else
            {
                <span class="badge bg-success ms-2">All stocked</span>
            }
        </h5>
        <p class="text-muted">
            Polling every 10 seconds for warehouse <strong>@WarehouseState.CurrentWarehouseId</strong>.
            @if (_lastPollTime.HasValue)
            {
                <br /><small>Last checked: @_lastPollTime.Value.ToString("HH:mm:ss")</small>
            }
        </p>
    </div>
</div>

@code {
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private DateTime? _lastPollTime;
    private Action? _warehouseHandler;
    private Action? _alertHandler;

    protected override void OnInitialized()
    {
        _warehouseHandler = () => InvokeAsync(OnWarehouseChanged);
        WarehouseState.OnChange += _warehouseHandler;

        _alertHandler = () => InvokeAsync(StateHasChanged);
        AlertService.OnAlertDataChanged += _alertHandler;
    }

    protected override async Task OnInitializedAsync()
    {
        await StartPollingAsync();
    }

    private async Task OnWarehouseChanged()
    {
        // Warehouse changed — restart polling for the new warehouse
        await StopPollingAsync();
        await PollOnceAsync();
        await StartPollingAsync();
        StateHasChanged();
    }

    private async Task StartPollingAsync()
    {
        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));

        _ = PollLoopAsync(_cts.Token);
        await Task.CompletedTask;
    }

    private async Task PollLoopAsync(CancellationToken token)
    {
        try
        {
            while (await _timer!.WaitForNextTickAsync(token))
            {
                await PollOnceAsync();
            }
        }
        catch (OperationCanceledException)
        {
            // Expected on dispose/cancellation
        }
    }

    private async Task PollOnceAsync()
    {
        var count = await AlertService.GetLowStockCountAsync(WarehouseState.CurrentWarehouseId);
        _lastPollTime = DateTime.Now;
        // Update the shared service — this notifies ALL subscribers (sidebar badge, this page, etc.)
        AlertService.UpdateAlertCount(count);
    }

    private async Task StopPollingAsync()
    {
        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
            _cts = null;
        }
        _timer?.Dispose();
        _timer = null;
    }

    public async ValueTask DisposeAsync()
    {
        await StopPollingAsync();

        if (_warehouseHandler is not null)
            WarehouseState.OnChange -= _warehouseHandler;

        if (_alertHandler is not null)
            AlertService.OnAlertDataChanged -= _alertHandler;
    }
}

